interface MovieRowProps {
  title: string;
  movies: Movie[];
  onSelect: (movie: Movie) => void;
  onPlay: (movie: Movie) => void;
  myList: string[];
  toggleMyList: (id: string, e: React.MouseEvent) => void;
}

function MovieRow({ title, movies, onSelect, onPlay, myList, toggleMyList }: MovieRowProps) {
  const rowRef = useRef<HTMLDivElement>(null);

  const handleScroll = (direction: 'left' | 'right') => {
    if (rowRef.current) {
      const { scrollLeft, clientWidth } = rowRef.current;
      const scrollAmount = clientWidth * 0.75;
      rowRef.current.scrollTo({
        left: direction === 'left' ? scrollLeft - scrollAmount : scrollLeft + scrollAmount,
        behavior: 'smooth'
      });
    }
  };

  if (movies.length === 0) return null;

  return (
    <div className="space-y-2 group/row">
      <h2 className="text-lg md:text-xl font-bold text-zinc-100 tracking-wide flex items-center justify-between">
        <span>{title}</span>
        <span className="text-xs text-red-500 cursor-pointer opacity-0 group-hover/row:opacity-100 transition duration-300">Explore All &gt;</span>
      </h2>

      <div className="relative">
        {/* Left Arrow */}
        <button 
          onClick={() => handleScroll('left')}
          className="absolute left-0 top-0 bottom-0 z-20 bg-black/60 hover:bg-black/80 text-white w-10 flex items-center justify-center opacity-0 group-hover/row:opacity-100 transition duration-300 rounded-r"
        >
          &lt;
        </button>

        {/* Movies Container */}
        <div 
          ref={rowRef}
          className="flex space-x-3 overflow-x-auto scrollbar-none py-4 px-1 scroll-smooth"
          style={{ scrollbarWidth: 'none', msOverflowStyle: 'none' }}
        >
          {movies.map(movie => (
            <MovieCard 
              key={movie.id} 
              movie={movie} 
              onSelect={onSelect} 
              onPlay={onPlay}
              isSaved={myList.includes(movie.id)}
              onToggleList={toggleMyList}
            />
          ))}
        </div>

        {/* Right Arrow */}
        <button 
          onClick={() => handleScroll('right')}
          className="absolute right-0 top-0 bottom-0 z-20 bg-black/60 hover:bg-black/80 text-white w-10 flex items-center justify-center opacity-0 group-hover/row:opacity-100 transition duration-300 rounded-l"
        >
          &gt;
        </button>
      </div>
    </div>
  );
}

interface MovieCardProps {
  movie: Movie;
  onSelect: (movie: Movie) => void;
  onPlay: (movie: Movie) => void;
  isSaved: boolean;
  onToggleList: (id: string, e: React.MouseEvent) => void;
}

function MovieCard({ movie, onSelect, onPlay, isSaved, onToggleList }: MovieCardProps) {
  return (
    <div 
      onClick={() => onSelect(movie)}
      className="flex-none w-48 md:w-60 h-28 md:h-36 bg-zinc-900 rounded-md overflow-hidden relative cursor-pointer group transition duration-300 transform hover:scale-105 hover:z-30 hover:shadow-2xl shadow-md border border-zinc-800"
    >
      <img src={movie.backdropUrl} alt={movie.title} className="w-full h-full object-cover group-hover:opacity-90 transition" />

      {/* Hover Overlay Details */}
      <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-black/40 to-transparent opacity-0 group-hover:opacity-100 transition duration-300 flex flex-col justify-end p-3">
        <p className="text-xs md:text-sm font-bold text-white truncate">{movie.title}</p>
        <div className="flex items-center space-x-2 mt-2">
          <button 
            onClick={(e) => { e.stopPropagation(); onPlay(movie); }}
            className="w-7 h-7 bg-white rounded-full flex items-center justify-center text-black hover:bg-zinc-200 transition shadow"
          >
            <Play className="w-3.5 h-3.5 fill-black ml-0.5" />
          </button>
          <button 
            onClick={(e) => onToggleList(movie.id, e)}
            className="w-7 h-7 border border-zinc-400 rounded-full flex items-center justify-center text-white hover:border-white transition"
          >
            {isSaved ? <Check className="w-3.5 h-3.5" /> : <Plus className="w-3.5 h-3.5" />}
          </button>
          <button 
            onClick={(e) => { e.stopPropagation(); onSelect(movie); }}
            className="w-7 h-7 border border-zinc-400 rounded-full flex items-center justify-center text-white hover:border-white transition ml-auto"
          >
            <ChevronDown className="w-3.5 h-3.5" />
          </button>
        </div>
        <div className="flex items-center space-x-2 mt-2 text-[10px] text-zinc-300">
          <span className="text-emerald-400 font-bold">{movie.match}% Match</span>
          <span className="border border-zinc-600 px-1 rounded">{movie.maturity}</span>
          <span>{movie.seasons ? `${movie.seasons}S` : movie.duration}</span>
        </div>
      </div>
    </div>
  );
}

