        <button 
          onClick={() => handleScroll('left')}
          className="absolute left-0 top-0 bottom-0 z-20 bg-black/60 hover:bg-black/80 text-white w-10 flex items-center justify-center opacity-0 group-hover/row:opacity-100 transition duration-300 rounded-r"
        >
          &lt;
        </button>

        {/* Movies Container */}
        <div 
          ref={rowRef}
          className="flex space-x-3 overflow-x-auto scrollbar-none py-4 px-1 scroll-smooth"
          style={{ scrollbarWidth: 'none', msOverflowStyle: 'none' }}
        >
          {movies.map(movie => (
            <MovieCard 
              key={movie.id} 
              movie={movie} 
              onSelect={onSelect} 
              onPlay={onPlay}
              isSaved={myList.includes(movie.id)}
              onToggleList={toggleMyList}
            />
          ))}
        </div>

        {/* Right Arrow */}
        <button 
          onClick={() => handleScroll('right')}
          className="absolute right-0 top-0 bottom-0 z-20 bg-black/60 hover:bg-black/80 text-white w-10 flex items-center justify-center opacity-0 group-hover/row:opacity-100 transition duration-300 rounded-l"
        >
          &gt;
        </button>
      </div>
    </div>
  );
}

